// src/lib/mcp/tools/create-booking.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.25.0";
import { z as z2 } from "npm:zod@^3.25.76";
var create_booking_default = defineTool3({
  name: "create_booking",
  title: "Create booking",
  description: "Create a new appointment for a business. The end time is derived from the service duration unless an explicit end_time is given.",
  inputSchema: {
    business_id: z2.string().uuid().describe("Business id from list_businesses."),
    service_id: z2.string().uuid().describe("Service id from list_services."),
    start_time: z2.string().describe("ISO 8601 start time of the appointment."),
    end_time: z2.string().optional().describe("ISO 8601 end time. Defaults to start + service duration."),
    customer_name: z2.string().describe("Customer full name."),
    customer_email: z2.string().optional().describe("Customer email address."),
    customer_phone: z2.string().optional().describe("Customer phone number."),
    staff_id: z2.string().uuid().optional().describe("Staff member id from list_staff."),
    notes: z2.string().optional().describe("Internal notes for this appointment."),
    status: z2.enum(["pending", "confirmed"]).optional().describe("Initial status. Defaults to pending.")
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async (input, ctx) => {
    const denied = requireAuth(ctx);
    if (denied) return denied;
    const supabase = supabaseForUser(ctx);
    const { data: service, error: serviceError } = await supabase.from("services").select("id, duration_minutes, price").eq("id", input.service_id).eq("business_id", input.business_id).maybeSingle();
    if (serviceError) return errorResult(serviceError.message);
    if (!service) return errorResult("Service not found for this business.");
    const start = new Date(input.start_time);
    if (Number.isNaN(start.getTime())) return errorResult("start_time is not a valid date.");
    const end = input.end_time ? new Date(input.end_time) : new Date(start.getTime() + (service.duration_minutes ?? 60) * 6e4);
    if (Number.isNaN(end.getTime())) return errorResult("end_time is not a valid date.");
    const { data, error } = await supabase.from("bookings").insert({
      business_id: input.business_id,
      service_id: input.service_id,
      staff_id: input.staff_id ?? null,
      start_time: start.toISOString(),
      end_time: end.toISOString(),
      customer_name: input.customer_name,
      customer_email: input.customer_email ?? null,
      customer_phone: input.customer_phone ?? null,
      notes: input.notes ?? null,
      status: input.status ?? "pending",
      total_price: service.price ?? null
    }).select("id, start_time, end_time, status").maybeSingle();
    if (error) return errorResult(error.message);
    return jsonResult({ booking: data });
  }
});

